def groups(row):
    gs,cur=[],[]
    for v in row:
        if v: cur.append(v)
        elif cur: gs.append(cur); cur=[]
    if cur: gs.append(cur)
    return gs

def transform(grid):
    w=len(grid[0])
    # key rows: rows containing a run of >=2 nonzero cells
    krows={i for i,row in enumerate(grid) if any(len(g)>1 for g in groups(row))}
    lookup={}
    for i in krows:
        for g in groups(grid[i]):
            for v in g: lookup.setdefault(v,g)
    out=[row[:] for row in grid]
    for i,row in enumerate(grid):
        if i in krows: continue
        for j,v in enumerate(row):
            if v and v in lookup:
                g=lookup[v]; s=j-g.index(v)
                for k,kv in enumerate(g):
                    c=s+k
                    if 0<=c<w: out[i][c]=kv
    return out

